const input = {
  avatar: clean(raw['Nhân vật'] || 'Tóc dài'),
  garment: clean(raw['Loại trang phục']),
  event: clean(raw['Sự kiện']),
  background: clean(raw['Bối cảnh'] || 'Sân trường'),
  favoriteColor: clean(raw['Màu yêu thích']),
  style: clean(raw['Phong cách']),
