const prepared = $('Chuẩn bị ảnh và trang phục').all().map(i => i.json);
const first = prepared[0];
const incoming = $input.all();
const esc = text => String(text ?? '').slice(0, 2000).replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
